const NO_COMPANY = '[not provided]';
// Contacts before Leads, email before phone.
const MATCH_ORDER = ['contactEmail', 'leadEmail', 'contactPhone', 'leadPhone'];

function soqlString(value) {
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
