  if (inquiry.phone && !current.Phone) fields.Phone = inquiry.phone;
  if (inquiry.phone && !current.Phone_E164__c) fields.Phone_E164__c = inquiry.phone;
  if (name.last && name.first && !current.FirstName) fields.FirstName = name.first;
